mod home;
fn main() {
    use std::io::Write;
    let mut record = std::fs::OpenOptions::new().create(true).append(true)
        .open(std::env::var_os("SWEEPX_NATIVE_HOME_RECORD").unwrap()).unwrap();
    record.write_all(b"{\"phase\":\"lookup_begin\"}\n").unwrap();
    let result = home::lookup();
    record.write_all(b"{\"phase\":\"lookup_end\"}\n").unwrap();
    match result {
        Ok(path) => println!("home={}", path.to_str().unwrap()),
        Err(reason) => println!("reason={reason}"),
    }
}

