#include <errno.h>
#include <pwd.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
int main(void) {
    char buffer[65536];
    struct passwd record = {0}, *result = NULL;
    uid_t uid = getuid();
    int status = getpwuid_r(uid, &record, buffer, sizeof(buffer), &result);
    if (status || !result || !result->pw_dir) return 2;
    uintptr_t first = (uintptr_t)buffer, pointer = (uintptr_t)result->pw_dir;
    if (pointer < first || pointer >= first + sizeof(buffer)) return 3;
    size_t remaining = sizeof(buffer) - (pointer - first);
    char *end = memchr(result->pw_dir, 0, remaining);
    if (!end || result->pw_uid != uid) return 4;
    if (write(STDOUT_FILENO, result->pw_dir, (size_t)(end - result->pw_dir)) < 0) return 5;
    return 0;
}

