import ctypes,os,selectors,signal,subprocess,time
from pathlib import Path
library=ctypes.CDLL('/private/tmp/sweepx-owned-wait-bridge.dylib')
observe=library.observe_owned_unreaped_child
observe.argtypes=[ctypes.c_int,ctypes.POINTER(ctypes.c_int),ctypes.POINTER(ctypes.c_int)];observe.restype=ctypes.c_int

def run_monitored(command,cwd,env):
    import sweepx_native_base_runner as base
    started=time.monotonic();output={'stdout':bytearray(),'stderr':bytearray()};retained=0;stop=None;diagnostic=None;exit_observation=None
    process=subprocess.Popen(command,cwd=cwd,env=env,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
    launched=time.monotonic()-started; selector=selectors.DefaultSelector();cleanup_attempted=False
    for stream,name in [(process.stdout,'stdout'),(process.stderr,'stderr')]:
        os.set_blocking(stream.fileno(),False);selector.register(stream,selectors.EVENT_READ,name)
    try:
        while True:
            elapsed=time.monotonic()-started
            if elapsed>=5:
                stop='deadline'
                # Only after the unchanged deadline fails. No poll/wait has consumed this
                # child's wait identity, so sampling cannot address a recycled process ID.
                sample_path=Path(cwd)/'owned-post-deadline-sample.txt'
                sampled=base.run_bounded(['/usr/bin/sample',str(process.pid),'1','1','-mayDie','-file',str(sample_path)],cwd,{'PATH':'/usr/bin:/bin','HOME':str(cwd)},timeout=3,maximum=128*1024)
                diagnostic={'plan':'One post-deadline sample of the exclusively owned/unreaped child; failure remains failure regardless of late progress.','sampleCommandPid':process.pid,'sampler':sampled,'sample':sample_path.read_text()[:128*1024] if sample_path.exists() else None}
                break
            for key,_ in selector.select(min(0.02,5-elapsed)) if selector.get_map() else []:
                chunk=os.read(key.fileobj.fileno(),min(65536,256*1024-retained+1))
                if not chunk:selector.unregister(key.fileobj)
                elif retained+len(chunk)>256*1024:stop='output_limit';break
                else:output[key.data].extend(chunk);retained+=len(chunk)
            if stop:break
            code=ctypes.c_int();status=ctypes.c_int();observed=observe(process.pid,ctypes.byref(code),ctypes.byref(status))
            if observed<0:raise RuntimeError('non-consuming wait ownership failed',observed)
            if observed:exit_observation={'code':code.value,'status':status.value}
            if not selector.get_map() and exit_observation is not None:break
            if not selector.get_map():time.sleep(min(0.001,max(0,5-(time.monotonic()-started))))
    finally:
        # Signal only before consuming the exclusively owned wait status. Never retry an
        # original numeric group after wait; zombie-only macOS groups may return EPERM.
        try:os.killpg(process.pid,signal.SIGKILL)
        except (ProcessLookupError,PermissionError):pass
        cleanup_attempted=True
        reaped=process.wait(timeout=2)
        selector.close();process.stdout.close();process.stderr.close()
    return {'status':reaped,'boundedFailure':stop,'stdout':output['stdout'].decode(),'stderr':output['stderr'].decode(),'retainedOutputBytes':retained,'launchedAfterSeconds':launched,'elapsedSeconds':time.monotonic()-started,'exitObservation':exit_observation,'postDeadlineDiagnostic':diagnostic}

