#include <errno.h>
#include <signal.h>
#include <sys/wait.h>
int observe_owned_unreaped_child(int pid, int *code, int *status) {
    siginfo_t info = {0};
    if (waitid(P_PID, (id_t)pid, &info, WEXITED | WNOHANG | WNOWAIT)) return -errno;
    if (!info.si_pid) return 0;
    if (info.si_pid != pid || info.si_signo != SIGCHLD) return -EINVAL;
    *code = info.si_code;
    *status = info.si_status;
    return 1;
}

